// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/health.ts, then fixed by hand where it says so.
// Health constants. Kept separate from needs.ts so survivors.ts can use them
// without an import cycle (same pattern as rest.ts and food.ts).
// All values are integers so the sim stays exactly deterministic.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Health
{

    public const int HEALTH_MAX = 1000;

    /// <summary>Health lost per tick while starving (satiety at 0): 1000 ticks, 100 s at 1x, from full to dead.</summary>
    public const int STARVE_DAMAGE = 1;

    /// <summary>Health regained per tick while asleep.</summary>
    public const int SLEEP_HEAL = 1;

    /// <summary>Awake and fed (not hungry): heal 1 every this many ticks.</summary>
    public const int AWAKE_HEAL_EVERY = 5;

    /// <summary>Below this, health shows red.</summary>
    public const int HEALTH_LOW = 300;

    /// <summary>Below 60%: hurt. Also the level a resting survivor must regain before getting up.</summary>
    public const int HEALTH_HURT = 600;

    /// <summary>Below 30%: critical.</summary>
    public const int HEALTH_CRITICAL = 300;

    /// <summary>Ticks per tile when hurt (normal is 4): 25% slower.</summary>
    public const int HURT_STEP_TICKS = 5;

    /// <summary>Hurt survivors skip one work tick in this many (3/4 speed).</summary>
    public const int HURT_WORK_SKIP_EVERY = 4;

    /// <summary>Health a bandage restores, and ticks it takes to apply one.</summary>
    public const int BANDAGE_HEAL = 300;

    public const int TREAT_TICKS = 20;

    /// <summary>A hurt survivor who found no bandage looks again after this many ticks.</summary>
    public const int TREAT_RETRY_TICKS = 20;

    public static bool isHurt(double health)
    {
        return health < HEALTH_HURT;
    }

    public static bool isCritical(double health)
    {
        return health < HEALTH_CRITICAL;
    }

    /// <summary>Does work advance this tick? Slowed survivors (hurt or miserable) lose one tick in HURT_WORK_SKIP_EVERY.</summary>
    public static bool worksThisTick(int tick, bool slowed)
    {
        return !Js.T(slowed) || ((tick % HURT_WORK_SKIP_EVERY) != 0);
    }
}
